import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")
_C = r"<!--(?:(?!-->).)*-->"
# A comment ending a line also takes the whitespace around it; others are just removed.
COMMENT = re.compile(rf"[ \t]*{_C}[ \t]*(?=\n|\Z)|{_C}", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def parse_changelog(text):
    releases = []
    current = None
    text = COMMENT.sub("", text.replace("\r\n", "\n").replace("\r", "\n"))
    for line in text.split("\n"):
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = re.sub(r"\n(?:[ \t]*\n)+", "\n\n", "\n".join(l.rstrip() if not l.strip() else l for l in release.body)).strip("\n")
            title = f"{release.version} ({release.date})" if release.date else release.version
            if not release.date:
                title = release.version
            return f"# {title}\n\n{body}\n"
    raise LookupError(version)

